import{_ as r,o as t,c as o,a3 as a}from"./chunks/framework.DBpCFmh2.js";const u=JSON.parse('{"title":"文件沙箱与安全控制","description":"本文聚焦 Agent 端的文件沙箱与安全控制，目标是说明：。","frontmatter":{"title":"文件沙箱与安全控制","description":"本文聚焦 Agent 端的文件沙箱与安全控制，目标是说明：。"},"headers":[],"relativePath":"本地代理服务/文件操作服务/文件沙箱与安全控制/index.md","filePath":"本地代理服务/文件操作服务/文件沙箱与安全控制/index.md","lastUpdated":null}'),l={name:"本地代理服务/文件操作服务/文件沙箱与安全控制/index.md"};function i(n,e,c,s,h,g){return t(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="文件沙箱与安全控制" tabindex="-1">文件沙箱与安全控制 <a class="header-anchor" href="#文件沙箱与安全控制" aria-label="Permalink to &quot;文件沙箱与安全控制&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js" target="_blank" rel="noreferrer">agent/src/security.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js" target="_blank" rel="noreferrer">agent/src/config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js" target="_blank" rel="noreferrer">agent/src/executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/agent-tools.js" target="_blank" rel="noreferrer">src/background/tools/agent-tools.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js" target="_blank" rel="noreferrer">src/background/tool-executor.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构与安全边界">项目结构与安全边界</a></li><li><a href="#核心安全组件">核心安全组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#路径白名单与规范化机制">路径白名单与规范化机制</a></li><li><a href="#目录遍历防护与符号链接检测">目录遍历防护与符号链接检测</a></li><li><a href="#权限模型与工作目录特殊处理">权限模型与工作目录特殊处理</a></li><li><a href="#命令分级管控与文件沙箱的边界">命令分级管控与文件沙箱的边界</a></li><li><a href="#完整路径安全检查流程">完整路径安全检查流程</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与资源限制">性能与资源限制</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#安全最佳实践">安全最佳实践</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文聚焦 Agent 端的文件沙箱与安全控制，目标是说明：</p><ul><li>路径输入如何被净化、规范化、硬阻止检查、白名单匹配和符号链接验证。</li><li><code>normalizePathFormat</code>、<code>allowedPaths</code>、<code>workdir</code>、<code>MEMORY_DIR</code>、<code>HARD_BLOCKED_PATHS</code>、<code>isHardBlocked</code> 等关键概念如何协作。</li><li>文件沙箱与命令分级管控的关系，以及当前实现的能力边界。</li><li>扩展端工具定义与 Agent 端执行器之间的职责划分。</li><li>面向生产的安全建议、审计日志和资源限制要点。</li></ul><p>本项目采用双进程架构：Chrome 扩展端负责用户交互、工具调度与网络访问策略；Agent 端（Node.js）负责本地文件系统、命令执行、长期记忆与 RAG。版本以 2.3.1 为准，Agent 源码修改后必须重启进程，新接口才生效。</p><h2 id="项目结构与安全边界" tabindex="-1">项目结构与安全边界 <a class="header-anchor" href="#项目结构与安全边界" aria-label="Permalink to &quot;项目结构与安全边界&quot;">​</a></h2><p>从安全视角看，本仓库中与文件沙箱直接相关的代码主要分布在以下位置：</p><ul><li>Agent 端安全核心：<code>agent/src/security.js</code></li><li>Agent 端配置与默认工作目录：<code>agent/src/config.js</code></li><li>Agent 端命令执行器：<code>agent/src/executor.js</code></li><li>扩展端 Agent 工具定义：<code>src/background/tools/agent-tools.js</code></li><li>扩展端工具执行与确认流程：<code>src/background/tool-executor.js</code></li></ul><pre class="mermaid">graph TB
Extension[&quot;扩展端&lt;br/&gt;tool-executor.js&quot;] --&gt; ToolDef[&quot;工具定义&lt;br/&gt;agent-tools.js&quot;]
Extension --&gt; AgentClient[&quot;本地 Agent 客户端&quot;]
AgentClient --&gt; AgentServer[&quot;Agent 服务端&quot;]
AgentServer --&gt; Security[&quot;安全模块&lt;br/&gt;security.js&quot;]
AgentServer --&gt; Config[&quot;配置模块&lt;br/&gt;config.js&quot;]
AgentServer --&gt; Executor[&quot;命令执行器&lt;br/&gt;executor.js&quot;]
Security --&gt; FS[&quot;操作系统文件系统&quot;]
Config --&gt; FS
Executor --&gt; FS
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1-L23" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1-L23</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/agent-tools.js#L1-L25" target="_blank" rel="noreferrer">src/background/tools/agent-tools.js#L1-L25</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L10" target="_blank" rel="noreferrer">agent/src/security.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L1-L20" target="_blank" rel="noreferrer">agent/src/config.js#L1-L20</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L1-L10" target="_blank" rel="noreferrer">agent/src/executor.js#L1-L10</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1-L23" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1-L23</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/agent-tools.js#L1-L25" target="_blank" rel="noreferrer">src/background/tools/agent-tools.js#L1-L25</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L10" target="_blank" rel="noreferrer">agent/src/security.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L1-L20" target="_blank" rel="noreferrer">agent/src/config.js#L1-L20</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L1-L10" target="_blank" rel="noreferrer">agent/src/executor.js#L1-L10</a></li></ul><h2 id="核心安全组件" tabindex="-1">核心安全组件 <a class="header-anchor" href="#核心安全组件" aria-label="Permalink to &quot;核心安全组件&quot;">​</a></h2><p>Agent 端的安全能力集中在 <code>security.js</code>，它同时承担两类职责：</p><ol><li><strong>文件沙箱</strong>：校验文件路径是否属于允许范围，防止越权读取、写入、删除或下载。</li><li><strong>命令分级管控</strong>：对 shell 命令进行黑名单、灰名单与强制放行判断。</li></ol><p>此外，<code>config.js</code> 提供默认工作目录、允许路径列表、记忆存储目录等基础配置；<code>executor.js</code> 负责命令执行、超时控制、输出缓冲与进程生命周期管理；<code>agent-tools.js</code> 暴露给扩展端的 Agent 工具定义；<code>tool-executor.js</code> 在扩展端组织工具调用、用户确认与审计记录。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L10" target="_blank" rel="noreferrer">agent/src/security.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L15-L39" target="_blank" rel="noreferrer">agent/src/config.js#L15-L39</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L1-L10" target="_blank" rel="noreferrer">agent/src/executor.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/agent-tools.js#L3-L25" target="_blank" rel="noreferrer">src/background/tools/agent-tools.js#L3-L25</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1-L23" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1-L23</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>下图展示一次“Agent 文件操作”的典型调用链：扩展端工具定义 → 扩展端工具执行 → 本地 Agent 客户端 → Agent 服务端 → 安全模块 → 文件系统。</p><pre class="mermaid">sequenceDiagram
participant LLM as &quot;大模型&quot;
participant Ext as &quot;扩展端工具执行器&quot;
participant Agent as &quot;本地 Agent 客户端&quot;
participant Server as &quot;Agent 服务端&quot;
participant Sec as &quot;安全模块&quot;
participant FS as &quot;文件系统&quot;
LLM-&gt;&gt;Ext : 调用 agent_file / agent_exec
Ext-&gt;&gt;Agent : 发起 HTTP/WebSocket 请求
Agent-&gt;&gt;Server : 转发到对应 API
Server-&gt;&gt;Sec : 传入 path/command 做安全检查
Sec--&gt;&gt;Server : 返回 allowed/denied/confirm
Server-&gt;&gt;FS : 通过后再执行读/写/删/查
FS--&gt;&gt;Server : 返回结果或错误
Server--&gt;&gt;Ext : 返回最终结果
Ext--&gt;&gt;LLM : 格式化后的结果
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/agent-tools.js#L3-L25" target="_blank" rel="noreferrer">src/background/tools/agent-tools.js#L3-L25</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1-L23" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1-L23</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><h2 id="路径白名单与规范化机制" tabindex="-1">路径白名单与规范化机制 <a class="header-anchor" href="#路径白名单与规范化机制" aria-label="Permalink to &quot;路径白名单与规范化机制&quot;">​</a></h2><h3 id="normalizepathformat-跨平台路径规范化" tabindex="-1">normalizePathFormat：跨平台路径规范化 <a class="header-anchor" href="#normalizepathformat-跨平台路径规范化" aria-label="Permalink to &quot;normalizePathFormat：跨平台路径规范化&quot;">​</a></h3><p><code>normalizePathFormat</code> 是路径进入沙箱前的第一道规范化步骤，主要解决 Windows、MSYS/Git Bash 与跨平台分隔符差异：</p><ul><li>修正异常盘符前导斜杠，例如 <code>/C:/</code> 归一为 <code>C:/</code>。</li><li>将 MSYS 风格路径 <code>/d/Users/...</code> 转换为 Windows 盘符形式 <code>D:/Users/...</code>。</li><li>统一反斜杠为正斜杠，交给 Node.js <code>path.resolve</code>/<code>normalize</code> 做最终归一。</li><li>将 Windows 盘符统一大写，避免小写盘符与大写白名单前缀比较失败。</li></ul><p>该函数支持单元测试时通过 <code>platformOverride</code> 覆盖平台行为，保证测试可预测。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L33-L60" target="_blank" rel="noreferrer">agent/src/security.js#L33-L60</a></li></ul><h3 id="allowedpaths-配置解析与自动追加" tabindex="-1">allowedPaths：配置解析与自动追加 <a class="header-anchor" href="#allowedpaths-配置解析与自动追加" aria-label="Permalink to &quot;allowedPaths：配置解析与自动追加&quot;">​</a></h3><p><code>allowedPaths</code> 来自 <code>config.js</code> 中的 <code>loadConfig()</code>：</p><ul><li>默认值为 <code>[WORKSPACE_DIR]</code>，即 <code>.ai-helper-agent/workspace</code>。</li><li>如果配置文件不存在，会创建默认配置并缓存。</li><li>加载配置后，会自动把 <code>SKILLS_DIR</code> 和 <code>WORKSPACE_DIR</code> 加入 <code>allowedPaths</code>，确保技能目录与工作目录始终可访问。</li><li>当 <code>allowedPaths</code> 为空时，安全模块会回退到使用 <code>workdir</code>。</li></ul><p>这意味着：</p><ul><li>用户可以在 <code>config.json</code> 中自定义允许路径。</li><li>但系统不会移除内置的工作目录和技能目录。</li><li>若用户清空 <code>allowedPaths</code>，实际仍会保留工作目录作为兜底。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L15-L39" target="_blank" rel="noreferrer">agent/src/config.js#L15-L39</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L107-L149" target="_blank" rel="noreferrer">agent/src/config.js#L107-L149</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L164-L178" target="_blank" rel="noreferrer">agent/src/security.js#L164-L178</a></li></ul><h3 id="workdir-工作目录的特殊放行逻辑" tabindex="-1">workdir：工作目录的特殊放行逻辑 <a class="header-anchor" href="#workdir-工作目录的特殊放行逻辑" aria-label="Permalink to &quot;workdir：工作目录的特殊放行逻辑&quot;">​</a></h3><p><code>workdir</code> 是用户当前选定的操作目录，由 <code>config.workdir</code> 决定，默认等于 <code>WORKSPACE_DIR</code>。安全模块对 <code>workdir</code> 有特殊处理：</p><ul><li>即使 <code>workdir</code> 不在 <code>allowedPaths</code> 中，只要目标路径落在 <code>workdir</code> 下，就优先放行。</li><li>放行前会对 <code>resolved</code> 路径调用 <code>realpath</code>，检查符号链接是否指向硬阻止目录。</li><li>如果路径不存在（ENOENT），且父目录可解析，则尝试构造真实路径继续校验；无法解析时拒绝。</li><li>如果符号链接绕过到硬阻止目录，直接拒绝。</li></ul><p>这体现了“用户明确选择的工作目录应始终可用，但不能绕过核心敏感文件保护”的设计。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L18-L19" target="_blank" rel="noreferrer">agent/src/config.js#L18-L19</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L142-L162" target="_blank" rel="noreferrer">agent/src/security.js#L142-L162</a></li></ul><h2 id="目录遍历防护与符号链接检测" tabindex="-1">目录遍历防护与符号链接检测 <a class="header-anchor" href="#目录遍历防护与符号链接检测" aria-label="Permalink to &quot;目录遍历防护与符号链接检测&quot;">​</a></h2><h3 id="hard-blocked-paths-硬阻止清单" tabindex="-1">HARD_BLOCKED_PATHS：硬阻止清单 <a class="header-anchor" href="#hard-blocked-paths-硬阻止清单" aria-label="Permalink to &quot;HARD_BLOCKED_PATHS：硬阻止清单&quot;">​</a></h3><p><code>HARD_BLOCKED_PATHS</code> 列出任何情况下都不可访问的核心敏感文件和目录，包括：</p><ul><li>Agent 配置文件 <code>config.json</code></li><li>配对记录 <code>pairings.json</code></li><li>MCP 服务器配置 <code>mcp_servers.json</code></li><li>日志目录 <code>logs</code></li><li>回收站目录 <code>.trash</code></li><li>内置技能状态 <code>builtin_skills_state.json</code></li><li>停用技能状态 <code>disabled_skills.json</code></li></ul><p>这些路径不会被白名单绕过，也不会因 <code>workdir</code> 特殊处理而放行。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L64-L75" target="_blank" rel="noreferrer">agent/src/security.js#L64-L75</a></li></ul><h3 id="ishardblocked-大小写不敏感比较" tabindex="-1">isHardBlocked：大小写不敏感比较 <a class="header-anchor" href="#ishardblocked-大小写不敏感比较" aria-label="Permalink to &quot;isHardBlocked：大小写不敏感比较&quot;">​</a></h3><p>Windows 文件系统不区分大小写，因此 <code>isHardBlocked</code> 在比较时会：</p><ul><li>根据平台决定是否转为小写。</li><li>对目录型硬阻止项，检查是否以该目录开头或完全相等。</li><li>对文件型硬阻止项，要求精确匹配。</li></ul><p>这样可防止通过 <code>.AI-HELPER-AGENT/CONFIG.JSON</code> 等大小写变换绕过硬阻止。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L77-L100" target="_blank" rel="noreferrer">agent/src/security.js#L77-L100</a></li></ul><h3 id="realpath-符号链接检测与绕过防护" tabindex="-1">realpath：符号链接检测与绕过防护 <a class="header-anchor" href="#realpath-符号链接检测与绕过防护" aria-label="Permalink to &quot;realpath：符号链接检测与绕过防护&quot;">​</a></h3><p><code>checkPath</code> 在多个阶段使用 <code>realpath</code>：</p><ol><li>对 <code>workdir</code> 内路径先做符号链接检测，再决定是否放行。</li><li>对普通白名单路径，先做前缀匹配，再解析真实路径。</li><li>对真实路径再次做硬阻止检查。</li><li>对真实路径再次做白名单前缀检查，防止符号链接跳转到其他允许目录。</li></ol><p>当路径不存在时，实现会向上回溯父目录，尝试解析已存在的父路径，再拼接剩余部分；如果所有父目录都无法解析，则拒绝。</p><pre class="mermaid">flowchart TD
Start([&quot;开始检查路径&quot;]) --&gt; Normalize[&quot;规范化路径&lt;br/&gt;normalizePathFormat + resolve + normalize&quot;]
Normalize --&gt; HardCheck[&quot;硬阻止检查&lt;br/&gt;isHardBlocked(normalized)&quot;]
HardCheck --&gt; |命中| DenyHard[&quot;拒绝：命中核心敏感文件&quot;]
HardCheck --&gt; |未命中| MemoryCheck[&quot;检查 MEMORY_DIR&quot;]
MemoryCheck --&gt; |命中| AllowMemory[&quot;放行：记忆存储目录&quot;]
MemoryCheck --&gt; |未命中| WorkdirCheck[&quot;检查工作目录&quot;]
WorkdirCheck --&gt; |命中| RealpathWorkdir[&quot;realpath 符号链接检测&quot;]
RealpathWorkdir --&gt; |绕过硬阻止| DenyHard
RealpathWorkdir --&gt; |未绕过| AllowWorkdir[&quot;放行：工作目录&quot;]
WorkdirCheck --&gt; |未命中| AllowedPathsCheck[&quot;allowedPaths 前缀匹配&quot;]
AllowedPathsCheck --&gt; |未命中| DenyNotInAllowed[&quot;拒绝：不在允许目录&quot;]
AllowedPathsCheck --&gt; |命中| RealpathAllowed[&quot;realpath 解析真实路径&quot;]
RealpathAllowed --&gt; RealpathHard[&quot;对 realPath 做硬阻止检查&quot;]
RealpathHard --&gt; |命中| DenyHard
RealpathHard --&gt; |未命中| RealpathAllowedPrefix[&quot;对 realPath 再做白名单前缀检查&quot;]
RealpathAllowedPrefix --&gt; |命中| AllowFinal[&quot;放行：最终授权&quot;]
RealpathAllowedPrefix --&gt; |未命中| DenyOutOfRange[&quot;拒绝：真实路径超出范围&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><h2 id="权限模型与工作目录特殊处理" tabindex="-1">权限模型与工作目录特殊处理 <a class="header-anchor" href="#权限模型与工作目录特殊处理" aria-label="Permalink to &quot;权限模型与工作目录特殊处理&quot;">​</a></h2><h3 id="memory-dir-记忆存储目录自动放行" tabindex="-1">MEMORY_DIR：记忆存储目录自动放行 <a class="header-anchor" href="#memory-dir-记忆存储目录自动放行" aria-label="Permalink to &quot;MEMORY_DIR：记忆存储目录自动放行&quot;">​</a></h3><p><code>MEMORY_DIR</code> 是 Agent 内部管理的长期记忆存储目录，位于 <code>.ai-helper-agent/memory</code>。安全模块将其视为系统级受信任目录：</p><ul><li>一旦路径命中 <code>MEMORY_DIR</code>，直接放行。</li><li>不需要经过 <code>allowedPaths</code> 配置。</li><li>这是合理的，因为记忆数据由 Agent 自身管理，不应被外部白名单策略阻断。</li></ul><p>注意：<code>MEMORY_DIR</code> 的放行发生在硬阻止检查之后，因此仍可防止直接访问硬阻止文件。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L13" target="_blank" rel="noreferrer">agent/src/config.js#L13</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L136-L140" target="_blank" rel="noreferrer">agent/src/security.js#L136-L140</a></li></ul><h3 id="系统目录保护" tabindex="-1">系统目录保护 <a class="header-anchor" href="#系统目录保护" aria-label="Permalink to &quot;系统目录保护&quot;">​</a></h3><p>系统目录保护主要通过两种方式实现：</p><ol><li><strong>硬阻止清单</strong>：禁止访问 Agent 配置、配对、日志、回收站、技能状态等核心文件。</li><li><strong>命令层拦截</strong>：命令分级管控会阻止破坏性系统命令，如递归删除系统目录、格式化磁盘、覆盖 <code>/etc/passwd</code>、fork bomb 等。</li></ol><p>需要明确的是：文件沙箱的 <code>allowedPaths</code> 只约束文件类工具；命令通道本身不受 <code>allowedPaths</code> 约束，因此像 <code>cat /etc/passwd</code> 这类“读取即外泄”的动作，应由更上层的网络/命令策略和用户确认机制控制。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L64-L75" target="_blank" rel="noreferrer">agent/src/security.js#L64-L75</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L231-L244" target="_blank" rel="noreferrer">agent/src/security.js#L231-L244</a></li></ul><h3 id="工作目录权限模型" tabindex="-1">工作目录权限模型 <a class="header-anchor" href="#工作目录权限模型" aria-label="Permalink to &quot;工作目录权限模型&quot;">​</a></h3><p>工作目录权限模型可以概括为：</p><ul><li><code>workdir</code> 是用户当前上下文的操作根目录。</li><li>所有相对路径都会基于 <code>workdir</code> 解析。</li><li><code>workdir</code> 下的路径优先放行，但仍需通过符号链接检测。</li><li>非 <code>workdir</code> 的路径必须命中 <code>allowedPaths</code>。</li><li>所有路径最终都要通过 <code>realpath</code> 的真实路径校验。</li></ul><pre class="mermaid">flowchart TD
Input[&quot;输入路径&quot;] --&gt; Relative{&quot;是否相对路径&quot;}
Relative --&gt; |是| ResolveWorkdir[&quot;基于 workdir 解析绝对路径&quot;]
Relative --&gt; |否| UseInput[&quot;直接使用输入路径&quot;]
ResolveWorkdir --&gt; Normalize[&quot;规范化&quot;]
UseInput --&gt; Normalize
Normalize --&gt; Decision[&quot;授权决策&quot;]
Decision --&gt; |workdir 内| FastAllow[&quot;快速放行 + 符号链接校验&quot;]
Decision --&gt; |allowedPaths 内| PrefixCheck[&quot;白名单前缀匹配&quot;]
PrefixCheck --&gt; RealpathVerify[&quot;realpath 真实路径验证&quot;]
RealpathVerify --&gt; FinalDecision[&quot;最终授权&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L122-L178" target="_blank" rel="noreferrer">agent/src/security.js#L122-L178</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L122-L178" target="_blank" rel="noreferrer">agent/src/security.js#L122-L178</a></li></ul><h2 id="命令分级管控与文件沙箱的边界" tabindex="-1">命令分级管控与文件沙箱的边界 <a class="header-anchor" href="#命令分级管控与文件沙箱的边界" aria-label="Permalink to &quot;命令分级管控与文件沙箱的边界&quot;">​</a></h2><h3 id="黑名单与灰名单" tabindex="-1">黑名单与灰名单 <a class="header-anchor" href="#黑名单与灰名单" aria-label="Permalink to &quot;黑名单与灰名单&quot;">​</a></h3><p>命令分级管控分为三类：</p><ul><li><strong>黑名单</strong>：绝对禁止，不可绕过。例如递归删除系统目录、格式化磁盘、覆盖系统关键文件、fork bomb、shebang 直接执行、恶意管道执行等。</li><li><strong>灰名单</strong>：需要用户确认。例如 <code>sudo</code>、<code>rm -rf</code>、<code>chmod 777</code>、网络外联、脚本解释器执行外部文件等。</li><li><strong>强制放行</strong>：用户确认后跳过灰名单，但黑名单仍然生效。</li></ul><h3 id="子命令拆分与包装器剥壳" tabindex="-1">子命令拆分与包装器剥壳 <a class="header-anchor" href="#子命令拆分与包装器剥壳" aria-label="Permalink to &quot;子命令拆分与包装器剥壳&quot;">​</a></h3><p>命令不是只看整串开头，而是：</p><ul><li>按 shell 控制符拆分为子命令段。</li><li>剥离 <code>nohup</code>、<code>sudo</code>、<code>env</code>、<code>timeout</code> 等包装器。</li><li>提取 <code>-c/-e</code>、<code>/c /k</code>、PowerShell <code>-Command/-EncodedCommand</code> 的内联载荷。</li><li>提取 <code>$( … )</code> 和反引号内的子命令。</li><li>对路径参数做归一化，防止 <code>//usr</code>、<code>/.//usr</code> 等写法绕过。</li></ul><h3 id="文件沙箱与命令通道的边界" tabindex="-1">文件沙箱与命令通道的边界 <a class="header-anchor" href="#文件沙箱与命令通道的边界" aria-label="Permalink to &quot;文件沙箱与命令通道的边界&quot;">​</a></h3><p>文档明确指出：命令通道不受 <code>allowedPaths</code> 约束。也就是说，文件沙箱不能替代命令安全网关。对于高危命令，应依赖黑名单、灰名单和用户确认流程。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L231-L244" target="_blank" rel="noreferrer">agent/src/security.js#L231-L244</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L285-L384" target="_blank" rel="noreferrer">agent/src/security.js#L285-L384</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L386-L447" target="_blank" rel="noreferrer">agent/src/security.js#L386-L447</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L644-L758" target="_blank" rel="noreferrer">agent/src/security.js#L644-L758</a></li></ul><h2 id="完整路径安全检查流程" tabindex="-1">完整路径安全检查流程 <a class="header-anchor" href="#完整路径安全检查流程" aria-label="Permalink to &quot;完整路径安全检查流程&quot;">​</a></h2><p>综合前面的分析，路径安全检查的完整流程如下：</p><ol><li><strong>输入验证</strong>：检查是否为字符串，空值直接拒绝。</li><li><strong>展开用户主目录</strong>：支持 <code>~</code> 和 <code>~/path</code>。</li><li><strong>路径规范化</strong>：调用 <code>normalizePathFormat</code>，然后 <code>resolve</code> + <code>normalize</code>。</li><li><strong>硬阻止检查</strong>：优先检查是否命中 <code>HARD_BLOCKED_PATHS</code>。</li><li><strong>记忆目录放行</strong>：命中 <code>MEMORY_DIR</code> 直接放行。</li><li><strong>工作目录放行</strong>：命中 <code>workdir</code> 放行，但需 <code>realpath</code> 检测符号链接。</li><li><strong>白名单匹配</strong>：检查是否在 <code>allowedPaths</code> 前缀范围内。</li><li><strong>符号链接验证</strong>：解析真实路径，再次检查硬阻止和白名单。</li><li><strong>最终授权决策</strong>：返回 <code>allowed</code>、<code>resolved</code> 或拒绝原因。</li></ol><pre class="mermaid">flowchart TD
A[&quot;输入 pathStr&quot;] --&gt; B[&quot;类型与空值校验&quot;]
B --&gt; C[&quot;展开 ~ 到 home 目录&quot;]
C --&gt; D[&quot;normalizePathFormat 规范化&quot;]
D --&gt; E[&quot;resolve + normalize 得到 normalized&quot;]
E --&gt; F{&quot;是否命中 HARD_BLOCKED_PATHS&quot;}
F --&gt; |是| G[&quot;拒绝：核心敏感文件&quot;]
F --&gt; |否| H{&quot;是否命中 MEMORY_DIR&quot;}
H --&gt; |是| I[&quot;放行：记忆存储目录&quot;]
H --&gt; |否| J{&quot;是否命中 workdir&quot;}
J --&gt; |是| K[&quot;realpath 符号链接检测&quot;]
K --&gt; |绕过硬阻止| G
K --&gt; |未绕过| L[&quot;放行：工作目录&quot;]
J --&gt; |否| M[&quot;allowedPaths 前缀匹配&quot;]
M --&gt; |未命中| N[&quot;拒绝：不在允许目录&quot;]
M --&gt; |命中| O[&quot;realpath 解析真实路径&quot;]
O --&gt; P{&quot;realPath 是否命中 HARD_BLOCKED_PATHS&quot;}
P --&gt; |是| G
P --&gt; |否| Q{&quot;realPath 是否命中 allowedPaths&quot;}
Q --&gt; |是| R[&quot;放行：最终授权&quot;]
Q --&gt; |否| S[&quot;拒绝：真实路径超出范围&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><pre class="mermaid">graph LR
Security[&quot;security.js&quot;] --&gt; Path[&quot;Node path 模块&quot;]
Security --&gt; FsPromises[&quot;fs/promises.realpath&quot;]
Security --&gt; Os[&quot;os.homedir / os.platform&quot;]
Security --&gt; Config[&quot;config.loadConfig&quot;]
Security --&gt; I18n[&quot;i18n.translate&quot;]
Config --&gt; FsSync[&quot;fs.readFileSync/writeFileSync/mkdirSync&quot;]
Config --&gt; Crypto[&quot;crypto-lite.encodeSecret/decodeSecret&quot;]
Executor[&quot;executor.js&quot;] --&gt; ChildProcess[&quot;child_process.spawn&quot;]
Executor --&gt; Config
Executor --&gt; I18n
Executor --&gt; Os
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L6" target="_blank" rel="noreferrer">agent/src/security.js#L1-L6</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L1-L7" target="_blank" rel="noreferrer">agent/src/config.js#L1-L7</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L1-L8" target="_blank" rel="noreferrer">agent/src/executor.js#L1-L8</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L6" target="_blank" rel="noreferrer">agent/src/security.js#L1-L6</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L1-L7" target="_blank" rel="noreferrer">agent/src/config.js#L1-L7</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L1-L8" target="_blank" rel="noreferrer">agent/src/executor.js#L1-L8</a></li></ul><h2 id="性能与资源限制" tabindex="-1">性能与资源限制 <a class="header-anchor" href="#性能与资源限制" aria-label="Permalink to &quot;性能与资源限制&quot;">​</a></h2><p>Agent 端在执行命令时实现了多项资源限制：</p><ul><li><strong>输出缓冲区上限</strong>：stdout/stderr 最多缓存 5MB，超过后截断并广播截断提示。</li><li><strong>命令超时策略</strong>：支持基础超时、延长次数上限和总预算封顶。</li><li><strong>静默进程终止</strong>：如果在预算期内无输出，视为挂起或静默失败，到期即杀。</li><li><strong>环境变量白名单</strong>：子进程只继承必要环境变量，避免泄露宿主敏感信息。</li><li><strong>进程树清理</strong>：Windows 使用 <code>taskkill /T /PID</code>，Unix 使用负 PID 终止进程组。</li></ul><p>这些机制与文件沙箱共同构成 Agent 端的安全基线：文件访问受路径白名单约束，命令执行受分级管控和资源限制约束。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L96-L114" target="_blank" rel="noreferrer">agent/src/executor.js#L96-L114</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L118-L156" target="_blank" rel="noreferrer">agent/src/executor.js#L118-L156</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L165-L186" target="_blank" rel="noreferrer">agent/src/executor.js#L165-L186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L495-L549" target="_blank" rel="noreferrer">agent/src/executor.js#L495-L549</a></li></ul><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><h3 id="路径被拒绝但确实在工作目录下" tabindex="-1">路径被拒绝但确实在工作目录下 <a class="header-anchor" href="#路径被拒绝但确实在工作目录下" aria-label="Permalink to &quot;路径被拒绝但确实在工作目录下&quot;">​</a></h3><p>可能原因：</p><ul><li>路径包含符号链接，且符号链接指向硬阻止目录。</li><li>路径尚未存在，父目录也无法解析。</li><li>路径大小写或分隔符导致规范化后不匹配。</li></ul><p>排查建议：</p><ul><li>检查路径是否经过 <code>realpath</code> 解析。</li><li>检查是否存在符号链接。</li><li>检查 <code>workdir</code> 是否与预期一致。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L148-L160" target="_blank" rel="noreferrer">agent/src/security.js#L148-L160</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L180-L209" target="_blank" rel="noreferrer">agent/src/security.js#L180-L209</a></li></ul><h3 id="白名单配置未生效" tabindex="-1">白名单配置未生效 <a class="header-anchor" href="#白名单配置未生效" aria-label="Permalink to &quot;白名单配置未生效&quot;">​</a></h3><p>可能原因：</p><ul><li>配置文件损坏或解析失败，回退到默认配置。</li><li><code>allowedPaths</code> 被自动追加了 <code>SKILLS_DIR</code> 和 <code>WORKSPACE_DIR</code>。</li><li>路径未正确规范化。</li></ul><p>排查建议：</p><ul><li>检查 <code>config.json</code> 是否可解析。</li><li>检查 <code>loadConfig</code> 是否返回默认配置。</li><li>检查路径是否经过 <code>normalizePathFormat</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L123-L149" target="_blank" rel="noreferrer">agent/src/config.js#L123-L149</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L164-L178" target="_blank" rel="noreferrer">agent/src/security.js#L164-L178</a></li></ul><h3 id="命令被拒绝但认为风险不高" tabindex="-1">命令被拒绝但认为风险不高 <a class="header-anchor" href="#命令被拒绝但认为风险不高" aria-label="Permalink to &quot;命令被拒绝但认为风险不高&quot;">​</a></h3><p>可能原因：</p><ul><li>命中黑名单，黑名单不可绕过。</li><li>命中灰名单，但未走用户确认流程。</li><li>命令包含内联载荷或子命令替换。</li></ul><p>排查建议：</p><ul><li>检查命令是否命中 <code>BLACKLIST_PATTERNS</code>。</li><li>检查是否命中 <code>GRAYLIST_PATTERNS</code>。</li><li>检查命令是否包含 <code>$( … )</code>、反引号、<code>-c/-e</code>、<code>-Command</code> 等特征。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L285-L384" target="_blank" rel="noreferrer">agent/src/security.js#L285-L384</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L644-L758" target="_blank" rel="noreferrer">agent/src/security.js#L644-L758</a></li></ul><h2 id="安全最佳实践" tabindex="-1">安全最佳实践 <a class="header-anchor" href="#安全最佳实践" aria-label="Permalink to &quot;安全最佳实践&quot;">​</a></h2><h3 id="输入净化" tabindex="-1">输入净化 <a class="header-anchor" href="#输入净化" aria-label="Permalink to &quot;输入净化&quot;">​</a></h3><ul><li>始终对路径进行类型校验，拒绝非字符串输入。</li><li>对用户输入的 <code>~</code> 展开为主目录，避免误判。</li><li>使用 <code>normalizePathFormat</code> 统一跨平台路径格式。</li><li>使用 <code>resolve</code> + <code>normalize</code> 消除 <code>..</code>、<code>.</code>、重复分隔符。</li></ul><h3 id="输出验证" tabindex="-1">输出验证 <a class="header-anchor" href="#输出验证" aria-label="Permalink to &quot;输出验证&quot;">​</a></h3><ul><li>对文件读取结果进行长度和内容校验。</li><li>对命令输出设置缓冲区上限，防止内存耗尽。</li><li>对截断输出广播提示，避免上层误以为完整成功。</li></ul><h3 id="资源限制" tabindex="-1">资源限制 <a class="header-anchor" href="#资源限制" aria-label="Permalink to &quot;资源限制&quot;">​</a></h3><ul><li>为命令执行设置合理超时。</li><li>对长时间无输出的命令及时终止。</li><li>限制子进程环境变量，避免敏感信息泄露。</li><li>使用进程组终止，防止僵尸进程残留。</li></ul><h3 id="审计日志记录" tabindex="-1">审计日志记录 <a class="header-anchor" href="#审计日志记录" aria-label="Permalink to &quot;审计日志记录&quot;">​</a></h3><p>扩展端工具执行会记录审计日志，包括工具名称、参数、结果、错误信息等。建议在 Agent 端也记录：</p><ul><li>每次路径检查的结果。</li><li>被拒绝的路径和原因。</li><li>被拒绝的命令和分类。</li><li>用户确认后的强制放行记录。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1-L23" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1-L23</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L96-L114" target="_blank" rel="noreferrer">agent/src/executor.js#L96-L114</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L118-L156" target="_blank" rel="noreferrer">agent/src/executor.js#L118-L156</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>Agent 端的文件沙箱与安全控制围绕“路径白名单 + 硬阻止清单 + 符号链接检测 + 工作目录特殊处理”构建，形成多层防御：</p><ul><li><code>normalizePathFormat</code> 解决跨平台路径差异。</li><li><code>allowedPaths</code> 提供可配置的访问范围。</li><li><code>workdir</code> 保证用户当前工作目录始终可用。</li><li><code>MEMORY_DIR</code> 作为系统级受信任目录自动放行。</li><li><code>HARD_BLOCKED_PATHS</code> 与 <code>isHardBlocked</code> 防止核心敏感文件被绕过。</li><li><code>realpath</code> 防止符号链接逃逸。</li><li>命令分级管控补充文件沙箱无法覆盖的命令安全风险。</li></ul><p>在生产环境中，应结合输入净化、输出验证、资源限制和审计日志，形成完整的可信执行边界。同时需注意：Agent 源码修改后必须重启进程，新接口才生效；命令通道不受 <code>allowedPaths</code> 约束，不能仅依赖文件沙箱保护系统安全。</p>`,159)])])}const b=r(l,[["render",i]]);export{u as __pageData,b as default};
